 assert.ok(['FULFILLED','RECOVERED'].includes(s.phase)&&s.pending===null&&s.proofIntent===null&&s.ownerAttached&&s.compiled,'PAGED_TERMINAL_OUTPUT_TERMINAL_OWNER');
 if(selection.role==='payout')assert.equal(s.phase,'FULFILLED','PAGED_TERMINAL_OUTPUT_NOT_ISSUED');
