function terminalPrepared(token){const value=terminalOutputPreparations.get(token),s=own.get(value?.controller);assert.ok(value&&s&&!s.closed&&s.readRecovery,'PAGED_TERMINAL_OUTPUT_ORIGINAL_PREPARED');s.readRecovery.current();return value;}
export function readOriginalDevicePagedPrivatePreparedTerminalOutputWithdrawalV5(token){assert.equal(arguments.length,1);return terminalPrepared(token).metadata;}
