 assert.equal(arguments.length,1);const s=own.get(controller);assert.ok(s&&!s.closed&&s.readRecovery===null&&s.pending?.proof&&s.automation,'PAGED_AUTOMATION_RETAINED_PROOF_REQUIRED');
 assert.ok(['PROVE_R','PROVE_EDGE','PROVE_ADMISSION','PROVE_NODE','PROVE_T'].includes(s.pending.action)||s.pending.action==='PROVE_OUTPUT_W39'&&s.automation.terms.profile===A.DEVICE_PAGED_AUTOMATION_V5,'PAGED_AUTOMATION_RETAINED_PROOF_ACTION');
 const proof=retainedProofV4(s.descriptor,s.pending,controller.summary()),result=Object.freeze({public:controller.summary(),proof,privateReply:{type:'ack'},effectHealth:null});results.set(result,{controller,jobId:s.pending.jobId});
