 assert.equal(arguments.length,1);const s=own.get(controller);assert.ok(s&&!s.closed&&s.readRecovery===null&&s.pending?.proof,'PAGED_ORIGINAL_RETAINED_PROOF_REQUIRED');assert.ok(C.devicePagedGraphProvesV3(s.pending.action),'PAGED_ORIGINAL_RETAINED_PROOF_ACTION');
 const proof=retainedProofV4(s.descriptor,s.pending,controller.summary()),result=Object.freeze({public:controller.summary(),proof,privateReply:{type:'ack'},effectHealth:null});results.set(result,{controller,jobId:s.pending.jobId});return Object.freeze({jobId:s.pending.jobId,action:s.pending.action,result,automation:controller.automation()});
